(() => {
  const A = HP.App;
  window.__esc = [];
  if (!window.__escHooked) {
    window.__escHooked = true;
    const oSend = A.send.bind(A);
    A.send = (d) => { if (typeof d === 'string' && d.charCodeAt(0) === 0x1b) window.__esc.push('0x1b'); return oSend(d); };
  }
  window.__esc = [];
  window.__coords = null;
  const vis = [...document.querySelectorAll('#keybar .key')].filter(e => e.getBoundingClientRect().width > 0);
  const esc = vis.find(e => e.textContent.trim() === 'Esc');
  if (esc) { const r = esc.getBoundingClientRect(); window.__coords = { x: Math.round(r.x + r.width / 2), y: Math.round(r.y + r.height / 2) }; }
  const top = [...document.querySelectorAll('#topbar button, #topbar .tb-btn, #topbar [role=button]')].filter(e => e.getBoundingClientRect().width > 0);
  window.__topBtn = top.length ? (() => { const r = top[0].getBoundingClientRect(); return { x: Math.round(r.x + r.width / 2), y: Math.round(r.y + r.height / 2), t: top[0].textContent.trim().slice(0, 8) }; })() : null;
  return JSON.stringify({ Esc坐标: window.__coords, 顶栏对照按钮: window.__topBtn });
})()
